 /** Called only by the genuine Woo payment-complete hook; persisted native payment is required too. */
 public function predict_paid_order(\WC_Order $order):void {
  try{$fresh=new \WC_Order($order->get_id());if($fresh->get_id()!==$order->get_id()||true!==($this->authority)($fresh,'payment_confirmed',null)||!method_exists($fresh,'get_date_paid')){return;}$date=$fresh->get_date_paid();if(!$date instanceof \DateTimeInterface||$date->getTimestamp()<1){return;}$paid=RuleTime::from_epoch_microseconds($date->getTimestamp()*1000000);$hpos=class_exists('\\Automattic\\WooCommerce\\Utilities\\OrderUtil')&&\Automattic\WooCommerce\Utilities\OrderUtil::custom_orders_table_usage_is_enabled();$evidence=new ShipmentPaidEvidence($fresh->get_id(),$paid,$hpos);
   foreach($this->shipments->findByOrderId($fresh->get_id()) as $shipment){$stored=$this->read_for_order($shipment,$fresh);if(null===$stored||'relative_window'!==$stored->packet()->result_facts()['state']){continue;}$event=$evidence->event_key($shipment->delivery_group_id);if(null!==$stored->current()){continue;} // An already recorded event, or a later staff revision, never receives another payment prediction.
    $calendar_values=[];$runtime=[];try{$runtime=null===$this->runtime?[]:($this->runtime)();$refs=array_map(static fn(array $ref):PromiseCalendarReference=>PromiseCalendarReference::from_array($ref),$stored->packet()->input_facts()['calendar_refs']);if([]!==$refs){if(null===$this->calendars){throw new \RuntimeException('Original calendars unavailable.');}$calendar_values=$this->calendars->load_versions($refs);}}catch(\Throwable){$calendar_values=[];$runtime=[];}
    $prediction=(new PaymentConfirmedPromisePrediction())->calculate($stored->packet(),$paid,$runtime,$calendar_values,$event);if(null!==$this->runtime){try{if(($this->runtime)()!==$runtime){$prediction=(new PaymentConfirmedPromisePrediction())->calculate($stored->packet(),$paid,[],[],$event);}}catch(\Throwable){$prediction=(new PaymentConfirmedPromisePrediction())->calculate($stored->packet(),$paid,[],[],$event);}}$identity=$this->identity($shipment,ShipmentPromiseCommand::UPDATE,$event,null);$command=ShipmentPromiseCommand::update($identity,$this->binding,$shipment,$stored->row()['revision'],$prediction,null,$evidence);if(true===($this->authority)($fresh,'payment_confirmed',null)){$this->attempt($command,null,$fresh);}
   }
  }catch(\Throwable){/* Original relative promise and Woo payment history remain intact. */}
 }
 public function update_current(\WC_Order $order,int $shipment_id,int $expected_revision,ShipmentCurrentPromise $current,int $actor_user_id,string $idempotency_key,bool $reconcile=false):OperationAttemptResult {
  $request=RequestContext::create();try{$shipment=$this->shipments->findById($shipment_id);if(!$shipment instanceof Shipment||$shipment->order_id!==$order->get_id()||'staff_revision'!==$current->private_facts()['source']||true!==($this->authority)($order,'update_current',$actor_user_id)){throw new \RuntimeException();}$identity=$this->identity($shipment,ShipmentPromiseCommand::UPDATE,$idempotency_key,$actor_user_id);$command=ShipmentPromiseCommand::update($identity,$this->binding,$shipment,$expected_revision,$current,$actor_user_id);$result=$this->attempt($command,$request,$order,$reconcile);if(true!==($this->authority)($order,'update_current',$actor_user_id)){return new OperationAttemptResult(OperationOutcome::unconfirmed(new ContractError('outcome_unknown',$request,'reconcile_original_request')));}return $result;}catch(\Throwable){return new OperationAttemptResult(OperationOutcome::rejected(new ContractError('not_authorized',$request,'contact_support')));}
 }
 /** Authorized persisted immutable original/current history, independent of current policy availability. */
 public function read_for_order(Shipment $shipment,\WC_Order $order):?ShipmentPromiseStored {
  $session=null;try{if($shipment->id<1||$shipment->order_id!==$order->get_id()||true!==($this->authority)($order,'read',null)){return null;}$session=$this->connections->open();$this->binding->assert_session($session);($this->readiness??new ShipmentPromiseOperationReadiness())->assert_ready($session);if($session->in_transaction()||!$session->begin()){return null;}$repo=new WpdbShipmentPromiseRepository($session,$this->binding);$stored=$repo->load($shipment->id);if(null===$stored||$stored->row()['order_id']!==$shipment->order_id||$stored->row()['delivery_group_id']!==$shipment->delivery_group_id){return null;}$repo->assert_ack($stored);if(!$session->rollback()||!$session->retire()||true!==($this->authority)($order,'read',null)){return null;}return $stored;}catch(\Throwable){return null;}finally{if(null!==$session&&!$session->is_retired()){if($session->in_transaction()){try{$session->rollback();}catch(\Throwable){}}try{$session->retire();}catch(\Throwable){}}}
 }
 private function attempt(ShipmentPromiseCommand $command,?RequestContext $context,\WC_Order $order,bool $reconcile=false):OperationAttemptResult{$grant=ShipmentPromiseGrant::capture($command,$order,$this->authority,$this->connections,$this->readiness??new ShipmentPromiseOperationReadiness());$profile=ShipmentPromiseOperationProfile::for_command($command,$grant);$coordinator=new OperationCoordinator(new OperationProfileRegistry([$profile]),$this->connections,$this->readiness??new ShipmentPromiseOperationReadiness());return $reconcile?$coordinator->reconcile($command->identity,$command,$context??RequestContext::create()):$coordinator->attempt($command->identity,$command,$context??RequestContext::create());}
