 private function order_fingerprint(\WC_Order $order):string{$facts=[];foreach([\CetechDeliveryEngine\Application\Order\OrderDeliverySnapshot::META_ORDER_QUOTE_SNAPSHOT,\CetechDeliveryEngine\Application\Order\OrderDeliverySnapshot::META_ORDER_SNAPSHOT_VERSION,\CetechDeliveryEngine\Application\Order\DeliveryQuoteSnapshotEnvelope::META_FORMAT,\CetechDeliveryEngine\Application\Order\QuoteNativeOrderFacts::META_REFERENCE] as $key){$facts[$key]=$order->get_meta($key,true);}return hash('sha256',PromiseJson::encode($facts,65536));}
}
